// 项目实战“复刻面试自习室”第 23 关：自动化测试。
// 学习卡片由 .sites-runtime/cards/pj-test-*.mjs 生成（node .sites-runtime/lessons.mjs apply …），题目直接写在这里。
import type {AiLevel} from '../journey';

export const pjTest:AiLevel={id:'pj-test',title:'自动化测试',summary:'用各语言自带的测试工具写单元测试和接口测试，临时数据库保证测试独立，再把旧的验收脚本合成回归测试',lessons:[
  {title:'这一关做什么：自动化测试',body:'到现在为止，每一关都靠验收脚本检查：启动服务，再运行 python checks/check_lN.py。这已经是“自动化测试”了：让程序去检查程序，而不是每次手动点一遍。\n这一关把测试做完整：\n一、单元测试：用你选的语言自带的测试工具，直接测试一个函数，比如第 22 关检查题目是否合格的 clean；\n二、接口测试：在测试里启动应用，连一个临时数据库，发真正的请求，检查注册、登录、权限；\n三、回归测试：把前面各关的验收脚本合在一起跑一遍，确认新功能没有把旧功能改坏。\n以后每次修改代码，提交之前跑一遍测试。下一关部署时，还会让它在上线前自动运行。'},
  {title:'测试分几层：测试金字塔',body:'常见的测试分三层：\n单元测试：只测一个函数或一个类，不连数据库、不发网络请求。跑得极快（几毫秒），出错时一眼就能看出是哪个函数的问题。适合测“规则”：校验、判分、复习间隔这些。\n接口测试（也叫集成测试）：把几层连起来测，比如“处理请求的层 → 业务逻辑层 → 数据库”。慢一些，但能发现各层接不上的问题。\n端到端测试：像真实用户一样，从外面访问整个运行中的系统。我们的验收脚本就是这一类。最接近真实，但最慢，出错时也最难定位。\n“测试金字塔”的意思是：底层的单元测试写得最多，中间的接口测试少一些，顶上的端到端测试最少。'},
  {title:'好的测试是什么样的',body:'一、独立：每个测试自己准备数据，不依赖其他测试先跑，也不依赖你本地数据库里有什么。接口测试用一个临时数据库文件，测完就扔掉；\n二、可重复：跑一百遍结果都一样。随机的用户名、当前时间这类东西要小心；\n三、一个测试只检查一件事，名字写清楚检查的是什么，比如“难度超出范围时返回 400”；\n四、失败时说清楚：期望是什么，实际得到了什么。\n还有一种很常用的写法叫“表格驱动测试”：把多组“输入 → 期望结果”写成一张表（数组），用一个循环逐行检查。想多测一种情况，只要在表里加一行。'},
  {title:'回归测试：旧的验收脚本还有用',body:'“回归”是指以前好好的功能，因为新的修改坏掉了。比如第 22 关改了注册接口，有没有可能把第 9 关的登录改坏？\n防止回归最简单的办法：每次修改后，把以前所有的检查都再跑一遍。我们已经有十几个验收脚本，这一关的验收就是一个“总管”脚本，把 checks 文件夹里的脚本依次运行，汇总结果。\n有几个早期的脚本（第 3 到 6 关）会失败，因为它们检查的是后来有意改掉的行为：比如第 7 关起，题目列表从“整个数组”改成了“分页”。这种脚本要“退休”：总管脚本里有一个 RETIRED 名单，写明跳过它的原因。注意区分：是需求变了（让旧检查退休），还是代码改坏了（修代码）。'},
  {title:'各语言的测试工具和命令',body:'每种语言都有自己的测试工具，写法不同，思路一样：准备数据 → 调用 → 断言结果。',code:`Go       测试文件 xxx_test.go，函数 TestXxx(t *testing.T)    运行：go test ./...
Java     src/test/java 下的类，方法加 @Test（JUnit 5）      运行：mvnw test
Node.js  test 文件夹里的 xxx.test.js，用 node:test         运行：node --test
Python   tests 文件夹里的 test_xxx.py，函数 test_xxx（pytest） 运行：python -m pytest`,explain:[{at:'Go       测试文件',text:'Go 自带测试工具，测试文件和代码放在一起，go build 不会把它编译进程序。'},{at:'Java     src/test/java',text:'JUnit 5 是 Java 最常用的测试框架，Spring Boot 项目创建时就带上了。'},{at:'Node.js  test 文件夹',text:'Node.js 18 起自带 node:test，不用安装别的包。'},{at:'Python   tests 文件夹',text:'pytest 要先 pip install pytest。用 python -m pytest 运行，项目根目录会被加进导入路径，测试里才能 import app。'}]},
  {title:'任务一：单元测试：检查题目的规则',body:'给第 22 关的 clean（检查题目是否合格）写单元测试：用一张“输入 → 是否应该通过”的表格，逐行检查。重点测边界：正好 200 个字可以，201 个字不行。',variants:{go:{practice:{steps:['新建 internal/service/admin_test.go，补完 TODO。','运行 go test ./internal/service/ -v，看每个测试的名字和结果。','故意把 clean 里的 200 改成 100，再运行一次，看看测试怎样报告失败；看完改回来。'],expect:'=== RUN   TestClean/题目_201_个字\n--- PASS: TestClean (0.00s)\n--- PASS: TestCleanTrimsSpaces (0.00s)\nPASS\nok  	zixishi/internal/service	0.012s'},code:'// internal/service/admin_test.go\npackage service\n\nimport (\n    "errors"\n    "strings"\n    "testing"\n\n    "zixishi/internal/store"\n)\n\n// 一道合格的题目，每一行测试在它的基础上改一处\nvar goodQuestion = store.Question{Category: "go", Title: "defer 的执行顺序？", Answer: "后进先出。", Difficulty: 2}\n\nfunc TestClean(t *testing.T) {\n    tests := []struct {\n        name    string\n        change  func(q *store.Question)\n        wantErr bool\n    }{\n        {"合格的题目", func(q *store.Question) {}, false},\n        {"难度超出范围", func(q *store.Question) { q.Difficulty = 5 }, true},\n        {"科目有大写字母和空格", func(q *store.Question) { q.Category = "Bad Name" }, true},\n        // TODO 1：再加四行：题目只有空格（出错）、题目正好 200 个字（通过）、题目 201 个字（出错）、\n        //         没有参考答案（出错）。strings.Repeat("字", 200) 可以生成 200 个字\n    }\n    for _, tt := range tests {\n        t.Run(tt.name, func(t *testing.T) {\n            q := goodQuestion\n            tt.change(&q)\n            _, err := clean(q)\n            if tt.wantErr && !errors.Is(err, ErrInvalidQuestion) {\n                t.Errorf("期望返回 ErrInvalidQuestion，实际是 %v", err)\n            }\n            // TODO 2：反过来，期望通过（wantErr 是 false）却出错了，也用 t.Errorf 报告\n        })\n    }\n}\n\n// 检查 clean 会去掉首尾空格\nfunc TestCleanTrimsSpaces(t *testing.T) {\n    // TODO 3：题目写成 "  defer 的执行顺序？ "，clean 之后应该没有出错，并且 Title 是 "defer 的执行顺序？"\n    _ = strings.Repeat\n}',explain:[{at:'// internal/service/admin_test.go',to:'package service',text:'Go 的测试文件以 _test.go 结尾，和被测试的代码放在同一个文件夹、同一个包里，所以能直接调用小写开头的 clean。go build 不会编译测试文件，go test 才会。'},{at:'import (',to:'"zixishi/internal/store"',text:'testing 是 Go 自带的测试包。'},{at:'// 一道合格的题目',to:'var goodQuestion =',text:'准备一份合格的数据，每种情况只改一处，这样失败时就知道是哪一处的问题。'},{at:'func TestClean(t *testing.T) {',text:'测试函数的名字以 Test 开头，参数是 *testing.T，go test 会自动找到并运行它。'},{at:'tests := []struct {',to:'}{',text:'表格驱动测试：一个“匿名结构体”的切片，每一行是一种情况：名字、怎么修改题目、是否应该出错。'},{at:'{"合格的题目",',to:'{"科目有大写字母和空格",',text:'已经写好的三行。func(q *store.Question) { … } 是一个没有名字的函数，用来修改题目的某个字段。'},{at:'// TODO 1',to:'//         没有参考答案',text:'再加四种情况，要你补全。“正好 200 个字”和“201 个字”是边界：最容易写错的地方。'},{at:'for _, tt := range tests {',to:'tt.change(&q)',text:'逐行运行。t.Run 给每一行起一个子测试，失败时能看到是哪一行。q := goodQuestion 复制一份结构体，修改它不会影响别的行。'},{at:'_, err := clean(q)',to:'t.Errorf("期望返回 ErrInvalidQuestion，实际是 %v", err)',text:'第一种失败已经写好：期望出错，却没有返回 ErrInvalidQuestion。另一种要你补全。'},{at:'// 检查 clean 会去掉首尾空格',to:'_ = strings.Repeat',text:'第二个测试，要你补全。_ = strings.Repeat 只是让还没用到的 strings 包先能编译，写完 TODO 1 就删掉。'}],solution:{code:'// internal/service/admin_test.go\npackage service\n\nimport (\n    "errors"\n    "strings"\n    "testing"\n\n    "zixishi/internal/store"\n)\n\n// 一道合格的题目，每一行测试在它的基础上改一处\nvar goodQuestion = store.Question{Category: "go", Title: "defer 的执行顺序？", Answer: "后进先出。", Difficulty: 2}\n\nfunc TestClean(t *testing.T) {\n    tests := []struct {\n        name    string\n        change  func(q *store.Question)\n        wantErr bool\n    }{\n        {"合格的题目", func(q *store.Question) {}, false},\n        {"难度超出范围", func(q *store.Question) { q.Difficulty = 5 }, true},\n        {"科目有大写字母和空格", func(q *store.Question) { q.Category = "Bad Name" }, true},\n        {"题目只有空格", func(q *store.Question) { q.Title = "   " }, true},\n        {"题目正好 200 个字", func(q *store.Question) { q.Title = strings.Repeat("字", 200) }, false},\n        {"题目 201 个字", func(q *store.Question) { q.Title = strings.Repeat("字", 201) }, true},\n        {"没有参考答案", func(q *store.Question) { q.Answer = "" }, true},\n    }\n    for _, tt := range tests {\n        t.Run(tt.name, func(t *testing.T) {\n            q := goodQuestion\n            tt.change(&q)\n            _, err := clean(q)\n            if tt.wantErr && !errors.Is(err, ErrInvalidQuestion) {\n                t.Errorf("期望返回 ErrInvalidQuestion，实际是 %v", err)\n            }\n            if !tt.wantErr && err != nil {\n                t.Errorf("期望通过，实际出错：%v", err)\n            }\n        })\n    }\n}\n\nfunc TestCleanTrimsSpaces(t *testing.T) {\n    q := goodQuestion\n    q.Title = "  defer 的执行顺序？ "\n    got, err := clean(q)\n    if err != nil || got.Title != "defer 的执行顺序？" {\n        t.Errorf("期望去掉首尾空格，实际是 %q（错误：%v）", got.Title, err)\n    }\n}',explain:[{at:'// internal/service/admin_test.go',to:'package service',text:'Go 的测试文件以 _test.go 结尾，和被测试的代码放在同一个文件夹、同一个包里，所以能直接调用小写开头的 clean。go build 不会编译测试文件，go test 才会。'},{at:'import (',to:'"zixishi/internal/store"',text:'testing 是 Go 自带的测试包。'},{at:'// 一道合格的题目',to:'var goodQuestion =',text:'准备一份合格的数据，每种情况只改一处，这样失败时就知道是哪一处的问题。'},{at:'func TestClean(t *testing.T) {',text:'测试函数的名字以 Test 开头，参数是 *testing.T，go test 会自动找到并运行它。'},{at:'tests := []struct {',to:'}{',text:'表格驱动测试：一个“匿名结构体”的切片，每一行是一种情况：名字、怎么修改题目、是否应该出错。'},{at:'{"合格的题目",',to:'{"科目有大写字母和空格",',text:'已经写好的三行。func(q *store.Question) { … } 是一个没有名字的函数，用来修改题目的某个字段。'},{at:'{"题目只有空格",',to:'{"没有参考答案",',text:'补上的四行。200 个字应该通过、201 个字应该失败，这样边界两侧都测到了。'},{at:'for _, tt := range tests {',to:'tt.change(&q)',text:'t.Run 给每一行起一个子测试。q := goodQuestion 复制一份结构体，修改它不会影响别的行。'},{at:'_, err := clean(q)',to:'t.Errorf("期望通过，实际出错：%v", err)',text:'两种失败：该出错没出错，不该出错却出错了。t.Errorf 记下失败，测试继续跑完其他行。'},{at:'func TestCleanTrimsSpaces(t *testing.T) {',to:'t.Errorf("期望去掉首尾空格',text:'第二个测试：检查首尾空格被去掉了。%q 会给字符串加上引号，空格看得清楚。'}]}},java:{practice:{steps:['新建 src/test/java/com/example/zixishi/service/AdminServiceTest.java，补完 TODO。','运行 mvnw test（Windows 是 .\\mvnw.cmd test），看测试结果。故意把 clean 里的 200 改成 100 再运行一次，看看失败时的报告；看完改回来。'],expect:'[INFO] Tests run: 8, Failures: 0, Errors: 0, Skipped: 0\n[INFO] BUILD SUCCESS'},code:'// src/test/java/com/example/zixishi/service/AdminServiceTest.java\npackage com.example.zixishi.service;\n\nimport static org.junit.jupiter.api.Assertions.*;\n\nimport com.example.zixishi.model.Question;\nimport java.util.stream.Stream;\nimport org.junit.jupiter.api.Test;\nimport org.junit.jupiter.params.ParameterizedTest;\nimport org.junit.jupiter.params.provider.Arguments;\nimport org.junit.jupiter.params.provider.MethodSource;\n\nclass AdminServiceTest {\n\n    // clean 用不到数据库，所以 AdminRepository 传 null，管理员名单为空\n    private final AdminService admin = new AdminService(null, "");\n\n    // 表格：名字、科目、题目、答案、难度、是否应该通过\n    static Stream<Arguments> cases() {\n        return Stream.of(\n            Arguments.of("难度超出范围", "go", "defer 的执行顺序？", "后进先出。", 5, false),\n            Arguments.of("科目有大写字母和空格", "Bad Name", "defer 的执行顺序？", "后进先出。", 2, false),\n            // TODO 1：在这里再加四行（每行末尾有逗号）：题目只有空格（不通过）、题目正好 200 个字（通过）、\n            //         题目 201 个字（不通过）、没有参考答案（不通过）。"字".repeat(200) 可以生成 200 个字\n            Arguments.of("合格的题目", "go", "defer 的执行顺序？", "后进先出。", 2, true)\n        );\n    }\n\n    @ParameterizedTest(name = "{0}")\n    @MethodSource("cases")\n    void clean(String name, String category, String title, String answer, Integer difficulty, boolean ok) {\n        // TODO 2：应该通过时用 assertDoesNotThrow(() -> admin.clean(0, …))；\n        //         不应该通过时用 assertThrows(StudyService.StudyException.class, () -> …)，再检查它的 status 是 400\n    }\n\n    @Test\n    void cleanStripsSpaces() {\n        // TODO 3：clean 一道题目是 "  defer 的执行顺序？ " 的题，用 assertEquals 检查返回的 title() 没有首尾空格\n    }\n}',explain:[{at:'// src/test/java/com/example/zixishi/service/AdminServiceTest.java',to:'package com.example.zixishi.service;',text:'Java 的测试放在 src/test/java 下面，包名和被测试的类一样。用 start.spring.io 创建项目时已经带上了测试依赖（JUnit 5）。'},{at:'import static org.junit.jupiter.api.Assertions.*;',to:'import org.junit.jupiter.params.provider.MethodSource;',text:'Assertions 里是 assertEquals、assertThrows 这些“断言”：检查结果是不是期望的样子，不是就让测试失败。import static 让我们直接写方法名。'},{at:'class AdminServiceTest {',text:'测试类。JUnit 会运行里面所有带 @Test 或 @ParameterizedTest 的方法。'},{at:'// clean 用不到数据库',to:'private final AdminService admin = new AdminService(null, "");',text:'单元测试不启动 Spring，直接 new 一个服务对象。clean 不访问数据库，所以仓库传 null 就够了。'},{at:'// 表格：',to:'Arguments.of("科目有大写字母和空格",',text:'表格驱动测试：每个 Arguments.of(…) 是一行，依次是名字、科目、题目、答案、难度、是否应该通过。'},{at:'// TODO 1',to:'Arguments.of("合格的题目",',text:'再加四行，要你补全。“正好 200 个字”和“201 个字”是边界：最容易写错的地方。最后一行后面不能有逗号。'},{at:'@ParameterizedTest(name = "{0}")',to:'void clean(',text:'@ParameterizedTest 让 JUnit 把表格里的每一行各运行一次这个方法，@MethodSource 指定表格从哪个方法来，name = "{0}" 用第一列当显示的名字。'},{at:'// TODO 2',to:'}',text:'检查结果，要你补全。'},{at:'@Test',to:'void cleanStripsSpaces() {',text:'普通的单个测试，要你补全。'}],solution:{code:'// src/test/java/com/example/zixishi/service/AdminServiceTest.java\npackage com.example.zixishi.service;\n\nimport static org.junit.jupiter.api.Assertions.*;\n\nimport com.example.zixishi.model.Question;\nimport java.util.stream.Stream;\nimport org.junit.jupiter.api.Test;\nimport org.junit.jupiter.params.ParameterizedTest;\nimport org.junit.jupiter.params.provider.Arguments;\nimport org.junit.jupiter.params.provider.MethodSource;\n\nclass AdminServiceTest {\n\n    // clean 用不到数据库，所以 AdminRepository 传 null，管理员名单为空\n    private final AdminService admin = new AdminService(null, "");\n\n    // 表格：名字、科目、题目、答案、难度、是否应该通过\n    static Stream<Arguments> cases() {\n        return Stream.of(\n            Arguments.of("难度超出范围", "go", "defer 的执行顺序？", "后进先出。", 5, false),\n            Arguments.of("科目有大写字母和空格", "Bad Name", "defer 的执行顺序？", "后进先出。", 2, false),\n            Arguments.of("题目只有空格", "go", "   ", "后进先出。", 2, false),\n            Arguments.of("题目正好 200 个字", "go", "字".repeat(200), "后进先出。", 2, true),\n            Arguments.of("题目 201 个字", "go", "字".repeat(201), "后进先出。", 2, false),\n            Arguments.of("没有参考答案", "go", "defer 的执行顺序？", "", 2, false),\n            Arguments.of("合格的题目", "go", "defer 的执行顺序？", "后进先出。", 2, true)\n        );\n    }\n\n    @ParameterizedTest(name = "{0}")\n    @MethodSource("cases")\n    void clean(String name, String category, String title, String answer, Integer difficulty, boolean ok) {\n        if (ok) {\n            assertDoesNotThrow(() -> admin.clean(0, category, title, answer, difficulty));\n        } else {\n            StudyService.StudyException e = assertThrows(StudyService.StudyException.class,\n                () -> admin.clean(0, category, title, answer, difficulty));\n            assertEquals(400, e.status);\n        }\n    }\n\n    @Test\n    void cleanStripsSpaces() {\n        Question q = admin.clean(0, "go", "  defer 的执行顺序？ ", "后进先出。", 2);\n        assertEquals("defer 的执行顺序？", q.title());\n    }\n}',explain:[{at:'// src/test/java/com/example/zixishi/service/AdminServiceTest.java',to:'package com.example.zixishi.service;',text:'Java 的测试放在 src/test/java 下面，包名和被测试的类一样。用 start.spring.io 创建项目时已经带上了测试依赖（JUnit 5）。'},{at:'import static org.junit.jupiter.api.Assertions.*;',to:'import org.junit.jupiter.params.provider.MethodSource;',text:'Assertions 里是 assertEquals、assertThrows 这些“断言”：检查结果是不是期望的样子，不是就让测试失败。import static 让我们直接写方法名。'},{at:'class AdminServiceTest {',text:'测试类。JUnit 会运行里面所有带 @Test 或 @ParameterizedTest 的方法。'},{at:'// clean 用不到数据库',to:'private final AdminService admin = new AdminService(null, "");',text:'单元测试不启动 Spring，直接 new 一个服务对象。clean 不访问数据库，所以仓库传 null 就够了。'},{at:'// 表格：',to:'Arguments.of("科目有大写字母和空格",',text:'表格驱动测试：每个 Arguments.of(…) 是一行，依次是名字、科目、题目、答案、难度、是否应该通过。'},{at:'Arguments.of("题目只有空格",',to:'Arguments.of("合格的题目",',text:'补上的四行。200 个字应该通过、201 个字应该失败，这样边界两侧都测到了。最后一行后面不能有逗号。'},{at:'@ParameterizedTest(name = "{0}")',to:'void clean(',text:'@ParameterizedTest 让 JUnit 把表格里的每一行各运行一次这个方法，@MethodSource 指定表格从哪个方法来，name = "{0}" 用第一列当显示的名字。'},{at:'if (ok) {',to:'assertDoesNotThrow(',text:'应该通过：clean 不抛异常。() -> … 是一段“待会儿再执行”的代码（lambda）。'},{at:'} else {',to:'assertEquals(400, e.status);',text:'不应该通过：assertThrows 要求抛出指定的异常，并把它返回，再检查状态码是 400。'},{at:'@Test',to:'assertEquals("defer 的执行顺序？", q.title());',text:'assertEquals(期望, 实际)：不相等时测试失败，并显示两边的值。'}]}},node:{practice:{steps:['把 src/services/admin.js 最后的导出改成代码最后一部分的样子。','新建 test/admin.test.js，补完 TODO。','运行 node --test，看每个测试的名字和结果。故意把 clean 里的 200 改成 100 再运行一次，看看失败时的报告；看完改回来。'],expect:'✔ 合格的题目 (0.6ms)\n✔ 题目 201 个字 (0.2ms)\n✔ 去掉首尾空格 (0.1ms)\nℹ tests 8\nℹ pass 8\nℹ fail 0'},code:'// test/admin.test.js\nconst { test } = require("node:test");\nconst assert = require("node:assert/strict");\n\n// 引入管理服务时会打开数据库；测试用内存数据库（":memory:"），不碰你真实的数据\nprocess.env.DB_PATH = ":memory:";\nconst { clean, AdminError } = require("../src/services/admin");\n\n// 一道合格的题目，每一种情况在它的基础上改一处\nconst good = { category: "go", title: "defer 的执行顺序？", answer: "后进先出。", difficulty: 2 };\n\nconst cases = [\n  { name: "合格的题目", change: {}, ok: true },\n  { name: "难度超出范围", change: { difficulty: 5 }, ok: false },\n  { name: "科目有大写字母和空格", change: { category: "Bad Name" }, ok: false },\n  // TODO 1：再加四行：题目只有空格（不通过）、题目正好 200 个字（通过）、题目 201 个字（不通过）、\n  //         没有参考答案（不通过）。"字".repeat(200) 可以生成 200 个字\n];\n\nfor (const c of cases) {\n  test(c.name, () => {\n    const q = { ...good, ...c.change };\n    // TODO 2：应该通过时用 assert.doesNotThrow(() => clean(q))；\n    //         不应该通过时用 assert.throws(() => clean(q), AdminError)\n  });\n}\n\ntest("去掉首尾空格", () => {\n  // TODO 3：clean 一道题目是 "  defer 的执行顺序？ " 的题，用 assert.equal 检查返回的 title 没有首尾空格\n});\n\n// src/services/admin.js：最后一行导出时加上 clean，测试才能直接调用它\nmodule.exports = { AdminError, migrate, onRegister, requireAdmin, clean, create, update, remove };',explain:[{at:'// test/admin.test.js',to:'const assert = require("node:assert/strict");',text:'node:test 是 Node.js 自带的测试工具，node:assert 用来写“断言”：检查结果是不是期望的样子，不是就让测试失败。测试文件放在 test 文件夹里，名字以 .test.js 结尾。'},{at:'// 引入管理服务时',to:'const { clean, AdminError } = require("../src/services/admin");',text:'第 6 关的 database.js 在被 require 时就会打开数据库，所以要在 require 之前设置 DB_PATH。:memory: 是 SQLite 的内存数据库，测试结束就没了。'},{at:'// 一道合格的题目',to:'const good =',text:'准备一份合格的数据，每种情况只改一处，这样失败时就知道是哪一处的问题。'},{at:'const cases = [',to:'{ name: "科目有大写字母和空格",',text:'表格驱动测试：每一行是一种情况：名字、要修改的字段、是否应该通过。'},{at:'// TODO 1',to:'];',text:'再加四种情况，要你补全。“正好 200 个字”和“201 个字”是边界：最容易写错的地方。'},{at:'for (const c of cases) {',to:'const q = { ...good, ...c.change };',text:'每一行注册一个测试，名字就是这一行的 name。{ ...good, ...c.change } 复制合格的题目，再用 change 里的字段覆盖。'},{at:'// TODO 2',to:'});',text:'检查结果，要你补全。'},{at:'test("去掉首尾空格", () => {',to:'});',text:'第二种检查，要你补全。'},{at:'// src/services/admin.js',to:'module.exports = { AdminError, migrate, onRegister, requireAdmin, clean, create, update, remove };',text:'clean 原来没有导出。为了测试导出它，是很常见的做法。'}],solution:{code:'// test/admin.test.js\nconst { test } = require("node:test");\nconst assert = require("node:assert/strict");\n\n// 引入管理服务时会打开数据库；测试用内存数据库（":memory:"），不碰你真实的数据\nprocess.env.DB_PATH = ":memory:";\nconst { clean, AdminError } = require("../src/services/admin");\n\n// 一道合格的题目，每一种情况在它的基础上改一处\nconst good = { category: "go", title: "defer 的执行顺序？", answer: "后进先出。", difficulty: 2 };\n\nconst cases = [\n  { name: "合格的题目", change: {}, ok: true },\n  { name: "难度超出范围", change: { difficulty: 5 }, ok: false },\n  { name: "科目有大写字母和空格", change: { category: "Bad Name" }, ok: false },\n  { name: "题目只有空格", change: { title: "   " }, ok: false },\n  { name: "题目正好 200 个字", change: { title: "字".repeat(200) }, ok: true },\n  { name: "题目 201 个字", change: { title: "字".repeat(201) }, ok: false },\n  { name: "没有参考答案", change: { answer: "" }, ok: false },\n];\n\nfor (const c of cases) {\n  test(c.name, () => {\n    const q = { ...good, ...c.change };\n    if (c.ok) {\n      assert.doesNotThrow(() => clean(q));\n    } else {\n      assert.throws(() => clean(q), AdminError);\n    }\n  });\n}\n\ntest("去掉首尾空格", () => {\n  const q = clean({ ...good, title: "  defer 的执行顺序？ " });\n  assert.equal(q.title, "defer 的执行顺序？");\n});\n\n// src/services/admin.js：最后一行导出时加上 clean，测试才能直接调用它\nmodule.exports = { AdminError, migrate, onRegister, requireAdmin, clean, create, update, remove };',explain:[{at:'// test/admin.test.js',to:'const assert = require("node:assert/strict");',text:'node:test 是 Node.js 自带的测试工具，node:assert 用来写“断言”：检查结果是不是期望的样子，不是就让测试失败。测试文件放在 test 文件夹里，名字以 .test.js 结尾。'},{at:'// 引入管理服务时',to:'const { clean, AdminError } = require("../src/services/admin");',text:'第 6 关的 database.js 在被 require 时就会打开数据库，所以要在 require 之前设置 DB_PATH。:memory: 是 SQLite 的内存数据库，测试结束就没了。'},{at:'// 一道合格的题目',to:'const good =',text:'准备一份合格的数据，每种情况只改一处，这样失败时就知道是哪一处的问题。'},{at:'const cases = [',to:'{ name: "科目有大写字母和空格",',text:'表格驱动测试：每一行是一种情况：名字、要修改的字段、是否应该通过。'},{at:'{ name: "题目只有空格",',to:'];',text:'补上的四行。200 个字应该通过、201 个字应该失败，这样边界两侧都测到了。'},{at:'for (const c of cases) {',to:'const q = { ...good, ...c.change };',text:'每一行注册一个测试。{ ...good, ...c.change } 复制合格的题目，再用 change 里的字段覆盖。'},{at:'if (c.ok) {',to:'});',text:'应该通过：clean 不抛异常；不应该通过：抛出的是 AdminError（不是别的错误）。'},{at:'test("去掉首尾空格", () => {',to:'assert.equal(q.title, "defer 的执行顺序？");',text:'assert.equal(实际, 期望)：不相等时测试失败，并显示两边的值。'},{at:'// src/services/admin.js',to:'module.exports = { AdminError, migrate, onRegister, requireAdmin, clean, create, update, remove };',text:'clean 原来没有导出。为了测试导出它，是很常见的做法。'}]}},python:{practice:{steps:['pip install pytest 安装测试工具。','新建 tests/test_admin.py，补完 TODO。','在项目根目录运行 python -m pytest -v，看每个测试的名字和结果。故意把 clean 里的 200 改成 100 再运行一次，看看失败时的报告；看完改回来。'],expect:'tests/test_admin.py::test_clean[合格的题目] PASSED\ntests/test_admin.py::test_clean[题目 201 个字] PASSED\ntests/test_admin.py::test_clean_strips_spaces PASSED\n======== 8 passed in 0.05s ========'},code:'# tests/test_admin.py\nimport pytest\n\nfrom app.services.admin import AdminError, clean\n\n# 一道合格的题目，每一种情况在它的基础上改一处\nGOOD = {"category": "go", "title": "defer 的执行顺序？", "answer": "后进先出。", "difficulty": 2}\n\nCASES = [\n    ("合格的题目", {}, True),\n    ("难度超出范围", {"difficulty": 5}, False),\n    ("科目有大写字母和空格", {"category": "Bad Name"}, False),\n    # TODO 1：再加四行：题目只有空格（不通过）、题目正好 200 个字（通过）、题目 201 个字（不通过）、\n    #         没有参考答案（不通过）。"字" * 200 可以生成 200 个字\n]\n\n\n@pytest.mark.parametrize("name, change, ok", CASES, ids=[c[0] for c in CASES])\ndef test_clean(name, change, ok):\n    q = {**GOOD, **change}\n    # TODO 2：应该通过时直接调用 clean(**q)（抛出异常测试就失败）；\n    #         不应该通过时写在 with pytest.raises(AdminError): 里面\n    pass\n\n\ndef test_clean_strips_spaces():\n    # TODO 3：clean 一道题目是 "  defer 的执行顺序？ " 的题，用 assert 检查返回的 title 没有首尾空格\n    pass',explain:[{at:'# tests/test_admin.py',to:'import pytest',text:'pytest 是 Python 最常用的测试工具（pip install pytest 安装）。测试文件放在 tests 文件夹里，文件名和函数名都以 test_ 开头，pytest 会自动找到它们。'},{at:'from app.services.admin import AdminError, clean',text:'直接引入要测试的函数。'},{at:'# 一道合格的题目',to:'GOOD =',text:'准备一份合格的数据，每种情况只改一处，这样失败时就知道是哪一处的问题。'},{at:'CASES = [',to:'("科目有大写字母和空格",',text:'表格驱动测试：每一行是一种情况：名字、要修改的字段、是否应该通过。'},{at:'# TODO 1',to:']',text:'再加四种情况，要你补全。“正好 200 个字”和“201 个字”是边界：最容易写错的地方。'},{at:'@pytest.mark.parametrize(',to:'q = {**GOOD, **change}',text:'parametrize 让 pytest 把表格里的每一行各运行一次这个函数，ids 是每一行显示的名字。{**GOOD, **change} 复制合格的题目，再用 change 里的字段覆盖。'},{at:'# TODO 2',to:'    pass',text:'检查结果，要你补全。'},{at:'def test_clean_strips_spaces():',to:'    pass',text:'第二种检查，要你补全。'}],solution:{code:'# tests/test_admin.py\nimport pytest\n\nfrom app.services.admin import AdminError, clean\n\n# 一道合格的题目，每一种情况在它的基础上改一处\nGOOD = {"category": "go", "title": "defer 的执行顺序？", "answer": "后进先出。", "difficulty": 2}\n\nCASES = [\n    ("合格的题目", {}, True),\n    ("难度超出范围", {"difficulty": 5}, False),\n    ("科目有大写字母和空格", {"category": "Bad Name"}, False),\n    ("题目只有空格", {"title": "   "}, False),\n    ("题目正好 200 个字", {"title": "字" * 200}, True),\n    ("题目 201 个字", {"title": "字" * 201}, False),\n    ("没有参考答案", {"answer": ""}, False),\n]\n\n\n@pytest.mark.parametrize("name, change, ok", CASES, ids=[c[0] for c in CASES])\ndef test_clean(name, change, ok):\n    q = {**GOOD, **change}\n    if ok:\n        clean(**q)\n    else:\n        with pytest.raises(AdminError):\n            clean(**q)\n\n\ndef test_clean_strips_spaces():\n    q = clean(**{**GOOD, "title": "  defer 的执行顺序？ "})\n    assert q["title"] == "defer 的执行顺序？"',explain:[{at:'# tests/test_admin.py',to:'import pytest',text:'pytest 是 Python 最常用的测试工具（pip install pytest 安装）。测试文件放在 tests 文件夹里，文件名和函数名都以 test_ 开头，pytest 会自动找到它们。'},{at:'from app.services.admin import AdminError, clean',text:'直接引入要测试的函数。'},{at:'# 一道合格的题目',to:'GOOD =',text:'准备一份合格的数据，每种情况只改一处，这样失败时就知道是哪一处的问题。'},{at:'CASES = [',to:'("科目有大写字母和空格",',text:'表格驱动测试：每一行是一种情况：名字、要修改的字段、是否应该通过。'},{at:'("题目只有空格",',to:']',text:'补上的四行。200 个字应该通过、201 个字应该失败，这样边界两侧都测到了。'},{at:'@pytest.mark.parametrize(',to:'q = {**GOOD, **change}',text:'parametrize 让 pytest 把表格里的每一行各运行一次这个函数，ids 是每一行显示的名字。{**GOOD, **change} 复制合格的题目，再用 change 里的字段覆盖。'},{at:'if ok:',to:'clean(**q)',text:'clean(**q) 把字典拆成四个关键字参数。应该通过时，直接调用：抛出异常测试就会失败。'},{at:'else:',to:'clean(**q)',text:'不应该通过时，with pytest.raises(AdminError) 要求里面必须抛出 AdminError，没抛出测试就失败。'},{at:'def test_clean_strips_spaces():',to:'assert q["title"] == "defer 的执行顺序？"',text:'assert 后面的条件不成立时测试失败，pytest 会显示两边的值。'}]}}}},
  {title:'任务二：接口测试：注册、登录和权限',body:'在测试里启动应用，连一个临时数据库，像浏览器一样发请求：没登录 401、登录后 200、普通用户 403、管理员 201、不合格 400。每次运行都是全新的数据，不碰你真实的数据库。（Node.js 要先把 app.js 的“启动”部分分出来，测试才能引入它。）',variants:{go:{practice:{steps:['新建 internal/handler/api_test.go，读懂已经给出的部分，补完 TODO。','运行 go test ./... -v，所有测试都应该通过。不需要先启动服务：测试自己会启动。'],expect:'--- PASS: TestLoginThenMe (0.15s)\n--- PASS: TestAdminNeedsRole (0.31s)\nPASS\nok  	zixishi/internal/handler	0.52s'},code:'// internal/handler/api_test.go\npackage handler\n\nimport (\n    "bytes"\n    "encoding/json"\n    "net/http"\n    "net/http/cookiejar"\n    "net/http/httptest"\n    "path/filepath"\n    "testing"\n\n    "zixishi/internal/service"\n    "zixishi/internal/store"\n)\n\n// newTestServer 用临时数据库组装出一个测试用的服务；用户名 boss 是管理员\nfunc newTestServer(t *testing.T) *httptest.Server {\n    t.Helper()\n    qs, err := store.Open(filepath.Join(t.TempDir(), "test.db"))\n    if err != nil {\n        t.Fatal(err)\n    }\n    t.Cleanup(func() { qs.DB().Close() }) // 测试结束时关掉数据库，临时文件才能删掉\n    us, err := store.NewUserStore(qs.DB())\n    if err != nil {\n        t.Fatal(err)\n    }\n    if err := us.MigrateOAuth(); err != nil {\n        t.Fatal(err)\n    }\n    if err := us.MigrateRoles(nil); err != nil {\n        t.Fatal(err)\n    }\n    admin := service.NewAdminService(us, qs, []string{"boss"})\n    // 这里只测试登录和管理接口，用不到的服务传 nil\n    // 最后一个参数：静态页面版本是静态文件夹（这里用一个空的临时文件夹）；模板渲染版本是模板，改成传 nil\n    h := New(qs, service.NewAuthService(us), nil, nil, nil, nil, nil, nil, admin, t.TempDir())\n    srv := httptest.NewServer(h.Routes())\n    t.Cleanup(srv.Close)\n    return srv\n}\n\n// newClient 创建一个带 Cookie 罐子的客户端，像浏览器一样记住登录状态\nfunc newClient(t *testing.T) *http.Client {\n    jar, err := cookiejar.New(nil)\n    if err != nil {\n        t.Fatal(err)\n    }\n    return &http.Client{Jar: jar}\n}\n\n// call 发一个 JSON 请求，返回状态码\nfunc call(t *testing.T, c *http.Client, method, url string, body any) int {\n    t.Helper()\n    data, _ := json.Marshal(body)\n    req, _ := http.NewRequest(method, url, bytes.NewReader(data))\n    req.Header.Set("Content-Type", "application/json")\n    res, err := c.Do(req)\n    if err != nil {\n        t.Fatal(err)\n    }\n    res.Body.Close()\n    return res.StatusCode\n}\n\n// signUp 注册并登录\nfunc signUp(t *testing.T, c *http.Client, base, username string) {\n    user := map[string]string{"username": username, "password": "password123"}\n    if got := call(t, c, "POST", base+"/api/register", user); got != http.StatusCreated {\n        t.Fatalf("注册 %s：期望 201，实际 %d", username, got)\n    }\n    if got := call(t, c, "POST", base+"/api/login", user); got != http.StatusOK {\n        t.Fatalf("登录 %s：期望 200，实际 %d", username, got)\n    }\n}\n\nfunc TestLoginThenMe(t *testing.T) {\n    srv := newTestServer(t)\n    c := newClient(t)\n    if got := call(t, c, "GET", srv.URL+"/api/me", nil); got != http.StatusUnauthorized {\n        t.Errorf("没登录时 /api/me：期望 401，实际 %d", got)\n    }\n    signUp(t, c, srv.URL, "alice")\n    if got := call(t, c, "GET", srv.URL+"/api/me", nil); got != http.StatusOK {\n        t.Errorf("登录后 /api/me：期望 200，实际 %d", got)\n    }\n}\n\n// 普通用户 403，管理员 201，不合格的题目 400\nfunc TestAdminNeedsRole(t *testing.T) {\n    srv := newTestServer(t)\n    q := map[string]any{"category": "go", "title": "测试题", "answer": "答案", "difficulty": 1}\n    // TODO：一个客户端注册 alice，新增题目应该是 403；另一个客户端注册 boss，新增题目应该是 201；\n    //       再把 q["difficulty"] 改成 9，boss 新增应该是 400。每一步不符合期望就 t.Errorf\n    _ = q\n}',explain:[{at:'// internal/handler/api_test.go',to:'"zixishi/internal/store"',text:'接口测试放在 handler 包里。httptest 是 Go 自带的测试工具，能在测试里启动一个真正的 HTTP 服务；cookiejar 帮客户端记住 Cookie。'},{at:'// newTestServer',to:'t.Helper()',text:'测试用的“组装”函数，做的事和 main.go 一样，只是数据库换成临时的。t.Helper() 让出错时报告调用它的那一行。'},{at:'qs, err := store.Open(',to:'t.Fatal(err)',text:'t.TempDir() 是一个临时文件夹，测试结束自动删除。每个测试都有一个全新的空数据库，互不影响。t.Fatal 记下错误并立刻结束这个测试。'},{at:'t.Cleanup(func() { qs.DB().Close() })',text:'t.Cleanup 登记一个“测试结束时要做的事”：关掉数据库。先关掉，临时文件夹才能删掉（Windows 不允许删除还打开着的文件）。'},{at:'us, err := store.NewUserStore(qs.DB())',to:'admin := service.NewAdminService(us, qs, []string{"boss"})',text:'建用户表、执行两次迁移，名单里只有 boss。'},{at:'// 这里只测试登录和管理接口',to:'return srv',text:'用不到的服务传 nil，只要测试里不访问那些地址就没问题。httptest.NewServer 在一个随机的空闲端口启动服务，srv.URL 就是它的地址；t.Cleanup 登记“测试结束时关掉它”。'},{at:'// newClient',to:'return &http.Client{Jar: jar}',text:'每个客户端有自己的 Cookie 罐子，就像不同的浏览器，登录状态互不影响。'},{at:'// call 发一个 JSON 请求',to:'return res.StatusCode',text:'发请求的小工具：把 body 转成 JSON 发出去，只返回状态码。'},{at:'// signUp 注册并登录',to:'t.Fatalf("登录 %s：期望 200，实际 %d", username, got)',text:'先注册再登录。这一步失败了，后面就没法测，所以用 t.Fatalf 立刻停止。'},{at:'func TestLoginThenMe(t *testing.T) {',to:'t.Errorf("登录后 /api/me：期望 200，实际 %d", got)',text:'第一个接口测试：没登录 401，登录后 200。失败信息写清楚“期望什么、实际是什么”。'},{at:'// 普通用户 403',to:'_ = q',text:'权限的接口测试，要你补全。两个客户端就是两个人。'}],solution:{code:'// internal/handler/api_test.go\npackage handler\n\nimport (\n    "bytes"\n    "encoding/json"\n    "net/http"\n    "net/http/cookiejar"\n    "net/http/httptest"\n    "path/filepath"\n    "testing"\n\n    "zixishi/internal/service"\n    "zixishi/internal/store"\n)\n\n// newTestServer 用临时数据库组装出一个测试用的服务；用户名 boss 是管理员\nfunc newTestServer(t *testing.T) *httptest.Server {\n    t.Helper()\n    qs, err := store.Open(filepath.Join(t.TempDir(), "test.db"))\n    if err != nil {\n        t.Fatal(err)\n    }\n    t.Cleanup(func() { qs.DB().Close() }) // 测试结束时关掉数据库，临时文件才能删掉\n    us, err := store.NewUserStore(qs.DB())\n    if err != nil {\n        t.Fatal(err)\n    }\n    if err := us.MigrateOAuth(); err != nil {\n        t.Fatal(err)\n    }\n    if err := us.MigrateRoles(nil); err != nil {\n        t.Fatal(err)\n    }\n    admin := service.NewAdminService(us, qs, []string{"boss"})\n    // 这里只测试登录和管理接口，用不到的服务传 nil\n    // 最后一个参数：静态页面版本是静态文件夹（这里用一个空的临时文件夹）；模板渲染版本是模板，改成传 nil\n    h := New(qs, service.NewAuthService(us), nil, nil, nil, nil, nil, nil, admin, t.TempDir())\n    srv := httptest.NewServer(h.Routes())\n    t.Cleanup(srv.Close)\n    return srv\n}\n\n// newClient 创建一个带 Cookie 罐子的客户端，像浏览器一样记住登录状态\nfunc newClient(t *testing.T) *http.Client {\n    jar, err := cookiejar.New(nil)\n    if err != nil {\n        t.Fatal(err)\n    }\n    return &http.Client{Jar: jar}\n}\n\n// call 发一个 JSON 请求，返回状态码\nfunc call(t *testing.T, c *http.Client, method, url string, body any) int {\n    t.Helper()\n    data, _ := json.Marshal(body)\n    req, _ := http.NewRequest(method, url, bytes.NewReader(data))\n    req.Header.Set("Content-Type", "application/json")\n    res, err := c.Do(req)\n    if err != nil {\n        t.Fatal(err)\n    }\n    res.Body.Close()\n    return res.StatusCode\n}\n\n// signUp 注册并登录\nfunc signUp(t *testing.T, c *http.Client, base, username string) {\n    user := map[string]string{"username": username, "password": "password123"}\n    if got := call(t, c, "POST", base+"/api/register", user); got != http.StatusCreated {\n        t.Fatalf("注册 %s：期望 201，实际 %d", username, got)\n    }\n    if got := call(t, c, "POST", base+"/api/login", user); got != http.StatusOK {\n        t.Fatalf("登录 %s：期望 200，实际 %d", username, got)\n    }\n}\n\nfunc TestLoginThenMe(t *testing.T) {\n    srv := newTestServer(t)\n    c := newClient(t)\n    if got := call(t, c, "GET", srv.URL+"/api/me", nil); got != http.StatusUnauthorized {\n        t.Errorf("没登录时 /api/me：期望 401，实际 %d", got)\n    }\n    signUp(t, c, srv.URL, "alice")\n    if got := call(t, c, "GET", srv.URL+"/api/me", nil); got != http.StatusOK {\n        t.Errorf("登录后 /api/me：期望 200，实际 %d", got)\n    }\n}\n\nfunc TestAdminNeedsRole(t *testing.T) {\n    srv := newTestServer(t)\n    q := map[string]any{"category": "go", "title": "测试题", "answer": "答案", "difficulty": 1}\n\n    user := newClient(t)\n    signUp(t, user, srv.URL, "alice")\n    if got := call(t, user, "POST", srv.URL+"/api/admin/questions", q); got != http.StatusForbidden {\n        t.Errorf("普通用户新增题目：期望 403，实际 %d", got)\n    }\n\n    boss := newClient(t)\n    signUp(t, boss, srv.URL, "boss")\n    if got := call(t, boss, "POST", srv.URL+"/api/admin/questions", q); got != http.StatusCreated {\n        t.Errorf("管理员新增题目：期望 201，实际 %d", got)\n    }\n    q["difficulty"] = 9\n    if got := call(t, boss, "POST", srv.URL+"/api/admin/questions", q); got != http.StatusBadRequest {\n        t.Errorf("难度不合格：期望 400，实际 %d", got)\n    }\n}',explain:[{at:'// internal/handler/api_test.go',to:'"zixishi/internal/store"',text:'接口测试放在 handler 包里。httptest 是 Go 自带的测试工具，能在测试里启动一个真正的 HTTP 服务；cookiejar 帮客户端记住 Cookie。'},{at:'// newTestServer',to:'t.Helper()',text:'测试用的“组装”函数，做的事和 main.go 一样，只是数据库换成临时的。t.Helper() 让出错时报告调用它的那一行。'},{at:'qs, err := store.Open(',to:'t.Fatal(err)',text:'t.TempDir() 是一个临时文件夹，测试结束自动删除。每个测试都有一个全新的空数据库，互不影响。t.Fatal 记下错误并立刻结束这个测试。'},{at:'t.Cleanup(func() { qs.DB().Close() })',text:'t.Cleanup 登记一个“测试结束时要做的事”：关掉数据库。先关掉，临时文件夹才能删掉（Windows 不允许删除还打开着的文件）。'},{at:'us, err := store.NewUserStore(qs.DB())',to:'admin := service.NewAdminService(us, qs, []string{"boss"})',text:'建用户表、执行两次迁移，名单里只有 boss。'},{at:'// 这里只测试登录和管理接口',to:'return srv',text:'用不到的服务传 nil，只要测试里不访问那些地址就没问题。httptest.NewServer 在一个随机的空闲端口启动服务，srv.URL 就是它的地址；t.Cleanup 登记“测试结束时关掉它”。'},{at:'// newClient',to:'return &http.Client{Jar: jar}',text:'每个客户端有自己的 Cookie 罐子，就像不同的浏览器，登录状态互不影响。'},{at:'// call 发一个 JSON 请求',to:'return res.StatusCode',text:'发请求的小工具：把 body 转成 JSON 发出去，只返回状态码。'},{at:'// signUp 注册并登录',to:'t.Fatalf("登录 %s：期望 200，实际 %d", username, got)',text:'先注册再登录。这一步失败了，后面就没法测，所以用 t.Fatalf 立刻停止。'},{at:'func TestLoginThenMe(t *testing.T) {',to:'t.Errorf("登录后 /api/me：期望 200，实际 %d", got)',text:'第一个接口测试：没登录 401，登录后 200。失败信息写清楚“期望什么、实际是什么”。'},{at:'func TestAdminNeedsRole(t *testing.T) {',to:'q := map[string]any{',text:'新的测试有自己的服务和数据库。q 是要新增的题目。'},{at:'user := newClient(t)',to:'t.Errorf("普通用户新增题目：期望 403，实际 %d", got)',text:'普通用户：登录了但没有权限，403。'},{at:'boss := newClient(t)',to:'t.Errorf("管理员新增题目：期望 201，实际 %d", got)',text:'boss 在名单里，注册后就是管理员，新增成功 201。'},{at:'q["difficulty"] = 9',to:'t.Errorf("难度不合格：期望 400，实际 %d", got)',text:'同一个管理员提交不合格的题目，400。'}]}},java:{practice:{steps:['新建 src/test/java/com/example/zixishi/ApiTest.java，读懂已经给出的部分，补完 TODO。','运行 mvnw test，两个测试类都应该通过。不需要先启动服务：测试自己会启动。'],expect:'[INFO] Tests run: 2, Failures: 0, Errors: 0, Skipped: 0 -- in com.example.zixishi.ApiTest\n[INFO] Tests run: 10, Failures: 0, Errors: 0, Skipped: 0\n[INFO] BUILD SUCCESS'},code:'// src/test/java/com/example/zixishi/ApiTest.java\npackage com.example.zixishi;\n\nimport static org.junit.jupiter.api.Assertions.*;\n\nimport java.util.Map;\nimport org.junit.jupiter.api.Test;\nimport org.springframework.boot.test.context.SpringBootTest;\nimport org.springframework.boot.test.web.server.LocalServerPort;\nimport org.springframework.http.HttpHeaders;\nimport org.springframework.http.HttpMethod;\nimport org.springframework.http.HttpStatusCode;\nimport org.springframework.http.MediaType;\nimport org.springframework.http.ResponseEntity;\nimport org.springframework.web.client.RestClient;\n\n// 启动整个应用，端口随机；数据库换成 target 下面一个新文件，名单里只有 boss\n@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT, properties = {\n    "spring.datasource.url=jdbc:sqlite:target/test-${random.uuid}.db",\n    "ADMIN_USERNAMES=boss"})\nclass ApiTest {\n\n    @LocalServerPort\n    int port;\n\n    // 一个“客户端”：自己记住 session Cookie\n    class Client {\n        private final RestClient http = RestClient.builder().baseUrl("http://127.0.0.1:" + port)\n            .defaultStatusHandler(HttpStatusCode::isError, (request, response) -> {})\n            .build();\n        private String cookie = "";\n\n        // 发一个 JSON 请求，返回状态码\n        int call(HttpMethod method, String path, Object body) {\n            RestClient.RequestBodySpec spec = http.method(method).uri(path)\n                .contentType(MediaType.APPLICATION_JSON)\n                .headers(h -> {\n                    if (!cookie.isEmpty()) {\n                        h.set(HttpHeaders.COOKIE, cookie);\n                    }\n                });\n            if (body != null) {\n                spec = spec.body(body);\n            }\n            ResponseEntity<Void> res = spec.retrieve().toBodilessEntity();\n            String setCookie = res.getHeaders().getFirst(HttpHeaders.SET_COOKIE);\n            if (setCookie != null) {\n                cookie = setCookie.split(";")[0];\n            }\n            return res.getStatusCode().value();\n        }\n\n        // 注册并登录\n        void signUp(String username) {\n            Map<String, String> user = Map.of("username", username, "password", "password123");\n            assertEquals(201, call(HttpMethod.POST, "/api/register", user));\n            assertEquals(200, call(HttpMethod.POST, "/api/login", user));\n        }\n    }\n\n    @Test\n    void loginThenMe() {\n        Client c = new Client();\n        assertEquals(401, c.call(HttpMethod.GET, "/api/me", null));\n        c.signUp("alice");\n        assertEquals(200, c.call(HttpMethod.GET, "/api/me", null));\n    }\n\n    // 普通用户 403，管理员 201，不合格的题目 400\n    @Test\n    void adminNeedsRole() {\n        Map<String, Object> q = Map.of("category", "go", "title", "测试题", "answer", "答案", "difficulty", 1);\n        // TODO：一个 Client 注册 carol（别用 alice，另一个测试已经注册过了），新增题目应该是 403；\n        //       另一个 Client 注册 boss，新增题目应该是 201；难度换成 9 再新增，应该是 400\n    }\n}',explain:[{at:'// src/test/java/com/example/zixishi/ApiTest.java',to:'import org.springframework.web.client.RestClient;',text:'接口测试放在根包里。RestClient 是第 14 关用过的 HTTP 客户端，这里用它给测试中的服务发请求。'},{at:'// 启动整个应用',to:'"ADMIN_USERNAMES=boss"})',text:'@SpringBootTest 会把整个应用启动起来；RANDOM_PORT 用一个随机的空闲端口，不会和你正在运行的服务冲突。properties 覆盖配置：数据库换成 target 文件夹里的新文件（${random.uuid} 每次都不一样，mvn clean 会删掉它们），名单里只有 boss。'},{at:'class ApiTest {',to:'int port;',text:'@LocalServerPort 把实际用到的端口号注入进来。'},{at:'// 一个“客户端”',to:'private String cookie = "";',text:'每个 Client 对象就像一个浏览器，有自己的 Cookie。defaultStatusHandler 设成“出错的状态码也不抛异常”，因为我们正要检查 401、403 这些状态码。'},{at:'// 发一个 JSON 请求',to:'spec = spec.body(body);',text:'有 Cookie 就带上；有请求正文就转成 JSON 发出去。'},{at:'ResponseEntity<Void> res =',to:'return res.getStatusCode().value();',text:'只要状态码，不要正文。登录成功时服务器返回 Set-Cookie，取出“session=…”这一段记下来，以后的请求都带上。'},{at:'// 注册并登录',to:'assertEquals(200, call(HttpMethod.POST, "/api/login", user));',text:'先注册再登录，每一步都检查状态码。'},{at:'@Test',to:'assertEquals(200, c.call(HttpMethod.GET, "/api/me", null));',text:'第一个接口测试：没登录 401，登录后 200。'},{at:'// 普通用户 403',to:'Map<String, Object> q = Map.of(',text:'权限的接口测试，要你补全。两个 Client 就是两个人。'}],solution:{code:'// src/test/java/com/example/zixishi/ApiTest.java\npackage com.example.zixishi;\n\nimport static org.junit.jupiter.api.Assertions.*;\n\nimport java.util.Map;\nimport org.junit.jupiter.api.Test;\nimport org.springframework.boot.test.context.SpringBootTest;\nimport org.springframework.boot.test.web.server.LocalServerPort;\nimport org.springframework.http.HttpHeaders;\nimport org.springframework.http.HttpMethod;\nimport org.springframework.http.HttpStatusCode;\nimport org.springframework.http.MediaType;\nimport org.springframework.http.ResponseEntity;\nimport org.springframework.web.client.RestClient;\n\n// 启动整个应用，端口随机；数据库换成 target 下面一个新文件，名单里只有 boss\n@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT, properties = {\n    "spring.datasource.url=jdbc:sqlite:target/test-${random.uuid}.db",\n    "ADMIN_USERNAMES=boss"})\nclass ApiTest {\n\n    @LocalServerPort\n    int port;\n\n    // 一个“客户端”：自己记住 session Cookie\n    class Client {\n        private final RestClient http = RestClient.builder().baseUrl("http://127.0.0.1:" + port)\n            .defaultStatusHandler(HttpStatusCode::isError, (request, response) -> {})\n            .build();\n        private String cookie = "";\n\n        // 发一个 JSON 请求，返回状态码\n        int call(HttpMethod method, String path, Object body) {\n            RestClient.RequestBodySpec spec = http.method(method).uri(path)\n                .contentType(MediaType.APPLICATION_JSON)\n                .headers(h -> {\n                    if (!cookie.isEmpty()) {\n                        h.set(HttpHeaders.COOKIE, cookie);\n                    }\n                });\n            if (body != null) {\n                spec = spec.body(body);\n            }\n            ResponseEntity<Void> res = spec.retrieve().toBodilessEntity();\n            String setCookie = res.getHeaders().getFirst(HttpHeaders.SET_COOKIE);\n            if (setCookie != null) {\n                cookie = setCookie.split(";")[0];\n            }\n            return res.getStatusCode().value();\n        }\n\n        // 注册并登录\n        void signUp(String username) {\n            Map<String, String> user = Map.of("username", username, "password", "password123");\n            assertEquals(201, call(HttpMethod.POST, "/api/register", user));\n            assertEquals(200, call(HttpMethod.POST, "/api/login", user));\n        }\n    }\n\n    @Test\n    void loginThenMe() {\n        Client c = new Client();\n        assertEquals(401, c.call(HttpMethod.GET, "/api/me", null));\n        c.signUp("alice");\n        assertEquals(200, c.call(HttpMethod.GET, "/api/me", null));\n    }\n\n    @Test\n    void adminNeedsRole() {\n        Map<String, Object> q = Map.of("category", "go", "title", "测试题", "answer", "答案", "difficulty", 1);\n\n        Client user = new Client();\n        user.signUp("carol");\n        assertEquals(403, user.call(HttpMethod.POST, "/api/admin/questions", q));\n\n        Client boss = new Client();\n        boss.signUp("boss");\n        assertEquals(201, boss.call(HttpMethod.POST, "/api/admin/questions", q));\n        Map<String, Object> bad = Map.of("category", "go", "title", "测试题", "answer", "答案", "difficulty", 9);\n        assertEquals(400, boss.call(HttpMethod.POST, "/api/admin/questions", bad));\n    }\n}',explain:[{at:'// src/test/java/com/example/zixishi/ApiTest.java',to:'import org.springframework.web.client.RestClient;',text:'接口测试放在根包里。RestClient 是第 14 关用过的 HTTP 客户端，这里用它给测试中的服务发请求。'},{at:'// 启动整个应用',to:'"ADMIN_USERNAMES=boss"})',text:'@SpringBootTest 会把整个应用启动起来；RANDOM_PORT 用一个随机的空闲端口，不会和你正在运行的服务冲突。properties 覆盖配置：数据库换成 target 文件夹里的新文件（${random.uuid} 每次都不一样，mvn clean 会删掉它们），名单里只有 boss。'},{at:'class ApiTest {',to:'int port;',text:'@LocalServerPort 把实际用到的端口号注入进来。'},{at:'// 一个“客户端”',to:'private String cookie = "";',text:'每个 Client 对象就像一个浏览器，有自己的 Cookie。defaultStatusHandler 设成“出错的状态码也不抛异常”，因为我们正要检查 401、403 这些状态码。'},{at:'// 发一个 JSON 请求',to:'spec = spec.body(body);',text:'有 Cookie 就带上；有请求正文就转成 JSON 发出去。'},{at:'ResponseEntity<Void> res =',to:'return res.getStatusCode().value();',text:'只要状态码，不要正文。登录成功时服务器返回 Set-Cookie，取出“session=…”这一段记下来，以后的请求都带上。'},{at:'// 注册并登录',to:'assertEquals(200, call(HttpMethod.POST, "/api/login", user));',text:'先注册再登录，每一步都检查状态码。'},{at:'@Test',to:'assertEquals(200, c.call(HttpMethod.GET, "/api/me", null));',text:'第一个接口测试：没登录 401，登录后 200。'},{at:'@Test',to:'Map<String, Object> q = Map.of(',text:'第二个测试。q 是要新增的题目。Map.of 创建一个不能修改的 Map。'},{at:'Client user = new Client();',to:'assertEquals(403, user.call(',text:'普通用户：登录了但没有权限，403。'},{at:'Client boss = new Client();',to:'assertEquals(400, boss.call(',text:'boss 在名单里，注册后就是管理员：新增成功 201；难度不合格 400。'}]}},node:{practice:{steps:['按代码第一部分修改 app.js 的最后几行，然后 node app.js 确认服务照常启动。','新建 test/api.test.js，读懂已经给出的部分，补完 TODO。','运行 node --test，所有测试都应该通过。不需要先启动服务：测试自己会启动。'],expect:'✔ 没登录时 401，登录后 200 (95ms)\n✔ 普通用户 403，管理员 201，不合格的题目 400 (160ms)\nℹ pass 10\nℹ fail 0'},code:'// app.js：文件最后（从导入题目开始）改成下面这样\nmodule.exports = app;\n\n// 只有直接运行 node app.js 时才导入数据、启动服务；测试里 require("./app") 时不会执行\nif (require.main === module) {\n  const imported = importIfEmpty("data/questions.json");\n  if (imported > 0) {\n    console.log(`导入了 ${imported} 道题`);\n  }\n  require("./src/db/practice").importIfEmpty("data/practice.json");\n  require("./src/services/admin").migrate();\n  app.listen(port, () => {\n    console.log(`服务已启动：http://localhost:${port}`);\n  });\n}\n\n// test/api.test.js\nconst { test, before, after } = require("node:test");\nconst assert = require("node:assert/strict");\n\n// 在 require 应用之前设置：内存数据库，名单里只有 boss\nprocess.env.DB_PATH = ":memory:";\nprocess.env.ADMIN_USERNAMES = "boss";\nconst app = require("../app");\nrequire("../src/services/admin").migrate();\n\nlet server;\nlet base;\n\n// 所有测试开始前，在一个随机的空闲端口（0）启动服务；全部结束后关掉\nbefore(() => new Promise((resolve) => {\n  server = app.listen(0, () => {\n    base = `http://127.0.0.1:${server.address().port}`;\n    resolve();\n  });\n}));\nafter(() => server.close());\n\n// 创建一个“客户端”：自己记住 session Cookie，返回一个发 JSON 请求、得到状态码的函数\nfunction client() {\n  let cookie = "";\n  return async (method, path, body) => {\n    const res = await fetch(base + path, {\n      method,\n      headers: { "Content-Type": "application/json", Cookie: cookie },\n      body: body === undefined ? undefined : JSON.stringify(body),\n    });\n    const setCookie = res.headers.get("set-cookie");\n    if (setCookie) cookie = setCookie.split(";")[0];\n    return res.status;\n  };\n}\n\n// 注册并登录\nasync function signUp(call, username) {\n  const user = { username, password: "password123" };\n  assert.equal(await call("POST", "/api/register", user), 201);\n  assert.equal(await call("POST", "/api/login", user), 200);\n}\n\ntest("没登录时 401，登录后 200", async () => {\n  const call = client();\n  assert.equal(await call("GET", "/api/me"), 401);\n  await signUp(call, "alice");\n  assert.equal(await call("GET", "/api/me"), 200);\n});\n\ntest("普通用户 403，管理员 201，不合格的题目 400", async () => {\n  const q = { category: "go", title: "测试题", answer: "答案", difficulty: 1 };\n  // TODO：一个客户端注册 carol（别用 alice，上一个测试已经注册过了），新增题目应该是 403；\n  //       另一个客户端注册 boss，新增题目应该是 201；把难度改成 9 再新增，应该是 400\n});',explain:[{at:'// app.js：文件最后',to:'module.exports = app;',text:'把组装好的 app 导出，测试就能 require 它。'},{at:'// 只有直接运行 node app.js 时',to:'if (require.main === module) {',text:'require.main 是“直接运行的那个文件”。直接 node app.js 时它就是 app.js 自己（module）；被测试 require 时不是，下面的代码就不执行。'},{at:'const imported = importIfEmpty(',to:'console.log(`服务已启动：http://localhost:${port}`);',text:'原来文件最后的几步：导入数据、迁移角色列、启动服务，只是挪进了 if 里。'},{at:'// test/api.test.js',to:'const assert = require("node:assert/strict");',text:'接口测试。before、after 是“所有测试之前、之后”要做的事。'},{at:'// 在 require 应用之前设置',to:'require("../src/services/admin").migrate();',text:'数据库路径和管理员名单都是在 require 时读取的，所以先设置环境变量，再 require 应用。迁移角色列原来在启动部分，这里手动调用一次。内存数据库里没有题目，这些测试也用不到。'},{at:'let server;',to:'let base;',text:'服务对象和它的地址，before 里赋值。'},{at:'// 所有测试开始前',to:'after(() => server.close());',text:'listen(0) 让系统挑一个空闲端口，不会和你正在运行的服务（8080）冲突。server.address().port 取出实际的端口。'},{at:'// 创建一个“客户端”',to:'return res.status;',text:'每个客户端有自己的 Cookie，就像不同的浏览器。登录成功时服务器返回 Set-Cookie，取出“session=…”这一段记下来，以后的请求都带上。'},{at:'// 注册并登录',to:'assert.equal(await call("POST", "/api/login", user), 200);',text:'先注册再登录，每一步都检查状态码。'},{at:'test("没登录时 401，登录后 200"',to:'assert.equal(await call("GET", "/api/me"), 200);',text:'第一个接口测试：没登录 401，登录后 200。'},{at:'test("普通用户 403',to:'});',text:'权限的接口测试，要你补全。两个客户端就是两个人。'}],solution:{code:'// app.js：文件最后（从导入题目开始）改成下面这样\nmodule.exports = app;\n\n// 只有直接运行 node app.js 时才导入数据、启动服务；测试里 require("./app") 时不会执行\nif (require.main === module) {\n  const imported = importIfEmpty("data/questions.json");\n  if (imported > 0) {\n    console.log(`导入了 ${imported} 道题`);\n  }\n  require("./src/db/practice").importIfEmpty("data/practice.json");\n  require("./src/services/admin").migrate();\n  app.listen(port, () => {\n    console.log(`服务已启动：http://localhost:${port}`);\n  });\n}\n\n// test/api.test.js\nconst { test, before, after } = require("node:test");\nconst assert = require("node:assert/strict");\n\n// 在 require 应用之前设置：内存数据库，名单里只有 boss\nprocess.env.DB_PATH = ":memory:";\nprocess.env.ADMIN_USERNAMES = "boss";\nconst app = require("../app");\nrequire("../src/services/admin").migrate();\n\nlet server;\nlet base;\n\n// 所有测试开始前，在一个随机的空闲端口（0）启动服务；全部结束后关掉\nbefore(() => new Promise((resolve) => {\n  server = app.listen(0, () => {\n    base = `http://127.0.0.1:${server.address().port}`;\n    resolve();\n  });\n}));\nafter(() => server.close());\n\n// 创建一个“客户端”：自己记住 session Cookie，返回一个发 JSON 请求、得到状态码的函数\nfunction client() {\n  let cookie = "";\n  return async (method, path, body) => {\n    const res = await fetch(base + path, {\n      method,\n      headers: { "Content-Type": "application/json", Cookie: cookie },\n      body: body === undefined ? undefined : JSON.stringify(body),\n    });\n    const setCookie = res.headers.get("set-cookie");\n    if (setCookie) cookie = setCookie.split(";")[0];\n    return res.status;\n  };\n}\n\n// 注册并登录\nasync function signUp(call, username) {\n  const user = { username, password: "password123" };\n  assert.equal(await call("POST", "/api/register", user), 201);\n  assert.equal(await call("POST", "/api/login", user), 200);\n}\n\ntest("没登录时 401，登录后 200", async () => {\n  const call = client();\n  assert.equal(await call("GET", "/api/me"), 401);\n  await signUp(call, "alice");\n  assert.equal(await call("GET", "/api/me"), 200);\n});\n\ntest("普通用户 403，管理员 201，不合格的题目 400", async () => {\n  const q = { category: "go", title: "测试题", answer: "答案", difficulty: 1 };\n\n  const user = client();\n  await signUp(user, "carol");\n  assert.equal(await user("POST", "/api/admin/questions", q), 403);\n\n  const boss = client();\n  await signUp(boss, "boss");\n  assert.equal(await boss("POST", "/api/admin/questions", q), 201);\n  assert.equal(await boss("POST", "/api/admin/questions", { ...q, difficulty: 9 }), 400);\n});',explain:[{at:'// app.js：文件最后',to:'module.exports = app;',text:'把组装好的 app 导出，测试就能 require 它。'},{at:'// 只有直接运行 node app.js 时',to:'if (require.main === module) {',text:'require.main 是“直接运行的那个文件”。直接 node app.js 时它就是 app.js 自己（module）；被测试 require 时不是，下面的代码就不执行。'},{at:'const imported = importIfEmpty(',to:'console.log(`服务已启动：http://localhost:${port}`);',text:'原来文件最后的几步：导入数据、迁移角色列、启动服务，只是挪进了 if 里。'},{at:'// test/api.test.js',to:'const assert = require("node:assert/strict");',text:'接口测试。before、after 是“所有测试之前、之后”要做的事。'},{at:'// 在 require 应用之前设置',to:'require("../src/services/admin").migrate();',text:'数据库路径和管理员名单都是在 require 时读取的，所以先设置环境变量，再 require 应用。迁移角色列原来在启动部分，这里手动调用一次。内存数据库里没有题目，这些测试也用不到。'},{at:'let server;',to:'let base;',text:'服务对象和它的地址，before 里赋值。'},{at:'// 所有测试开始前',to:'after(() => server.close());',text:'listen(0) 让系统挑一个空闲端口，不会和你正在运行的服务（8080）冲突。server.address().port 取出实际的端口。'},{at:'// 创建一个“客户端”',to:'return res.status;',text:'每个客户端有自己的 Cookie，就像不同的浏览器。登录成功时服务器返回 Set-Cookie，取出“session=…”这一段记下来，以后的请求都带上。'},{at:'// 注册并登录',to:'assert.equal(await call("POST", "/api/login", user), 200);',text:'先注册再登录，每一步都检查状态码。'},{at:'test("没登录时 401，登录后 200"',to:'assert.equal(await call("GET", "/api/me"), 200);',text:'第一个接口测试：没登录 401，登录后 200。'},{at:'test("普通用户 403',to:'const q = {',text:'q 是要新增的题目。'},{at:'const user = client();',to:'assert.equal(await user("POST", "/api/admin/questions", q), 403);',text:'普通用户：登录了但没有权限，403。'},{at:'const boss = client();',to:'{ ...q, difficulty: 9 }), 400);',text:'boss 在名单里，注册后就是管理员：新增成功 201；难度不合格 400。'}]}},python:{practice:{steps:['新建 tests/conftest.py（代码第一部分）和 tests/test_api.py，读懂已经给出的部分，补完 TODO。','在项目根目录运行 python -m pytest -v，所有测试都应该通过。不需要先启动服务。'],expect:'tests/test_api.py::test_login_then_me PASSED\ntests/test_api.py::test_admin_needs_role PASSED\n======== 10 passed in 1.20s ========'},code:'# tests/conftest.py\nimport os\nimport tempfile\n\n# pytest 在导入任何测试文件之前先运行 conftest.py，所以在这里设置：临时数据库文件，名单里只有 boss\nos.environ["DB_PATH"] = os.path.join(tempfile.mkdtemp(), "test.db")\nos.environ["ADMIN_USERNAMES"] = "boss"\n\n\n# tests/test_api.py\nfrom fastapi.testclient import TestClient\n\nfrom app.database import init_db\nfrom app.services import admin as admin_service\nfrom main import app\n\ninit_db()\nadmin_service.migrate()\n\n\ndef sign_up(client, username):\n    """注册并登录"""\n    user = {"username": username, "password": "password123"}\n    assert client.post("/api/register", json=user).status_code == 201\n    assert client.post("/api/login", json=user).status_code == 200\n\n\ndef test_login_then_me():\n    client = TestClient(app)\n    assert client.get("/api/me").status_code == 401\n    sign_up(client, "alice")\n    assert client.get("/api/me").status_code == 200\n\n\ndef test_admin_needs_role():\n    """普通用户 403，管理员 201，不合格的题目 400"""\n    q = {"category": "go", "title": "测试题", "answer": "答案", "difficulty": 1}\n    # TODO：一个 TestClient 注册 carol（别用 alice，上一个测试已经注册过了），新增题目应该是 403；\n    #       另一个 TestClient 注册 boss，新增题目应该是 201；把难度改成 9 再新增，应该是 400',explain:[{at:'# tests/conftest.py',to:'import tempfile',text:'conftest.py 是 pytest 的“公共准备文件”，放在 tests 文件夹里。tempfile 用来创建临时文件夹。'},{at:'# pytest 在导入任何测试文件之前',to:'os.environ["ADMIN_USERNAMES"] = "boss"',text:'数据库路径和管理员名单都是在导入时读取的（第一个导入 app.database 的文件就决定了用哪个数据库），所以必须在所有测试文件之前设置，写在 conftest.py 里最稳妥。数据库用临时文件夹里的新文件，不碰你真实的数据。（不用 :memory: 内存数据库，因为我们每次查询都新开一个连接，内存数据库每个连接都是空的。）'},{at:'# tests/test_api.py',to:'from main import app',text:'接口测试。TestClient 不用真的启动服务，直接把请求交给 app 处理，还会像浏览器一样记住 Cookie。'},{at:'init_db()',to:'admin_service.migrate()',text:'原来在 if __name__ == "__main__": 里做的准备工作，这里手动做一遍：建表、导入题目、迁移角色列。'},{at:'def sign_up(client, username):',to:'assert client.post("/api/login", json=user).status_code == 200',text:'先注册再登录，每一步都检查状态码。json=… 会自动转成 JSON 正文。'},{at:'def test_login_then_me():',to:'assert client.get("/api/me").status_code == 200',text:'第一个接口测试：没登录 401，登录后 200。'},{at:'def test_admin_needs_role():',to:'q = {',text:'权限的接口测试，要你补全。两个 TestClient 就是两个人，各自记住自己的 Cookie。'}],solution:{code:'# tests/conftest.py\nimport os\nimport tempfile\n\n# pytest 在导入任何测试文件之前先运行 conftest.py，所以在这里设置：临时数据库文件，名单里只有 boss\nos.environ["DB_PATH"] = os.path.join(tempfile.mkdtemp(), "test.db")\nos.environ["ADMIN_USERNAMES"] = "boss"\n\n\n# tests/test_api.py\nfrom fastapi.testclient import TestClient\n\nfrom app.database import init_db\nfrom app.services import admin as admin_service\nfrom main import app\n\ninit_db()\nadmin_service.migrate()\n\n\ndef sign_up(client, username):\n    """注册并登录"""\n    user = {"username": username, "password": "password123"}\n    assert client.post("/api/register", json=user).status_code == 201\n    assert client.post("/api/login", json=user).status_code == 200\n\n\ndef test_login_then_me():\n    client = TestClient(app)\n    assert client.get("/api/me").status_code == 401\n    sign_up(client, "alice")\n    assert client.get("/api/me").status_code == 200\n\n\ndef test_admin_needs_role():\n    q = {"category": "go", "title": "测试题", "answer": "答案", "difficulty": 1}\n\n    user = TestClient(app)\n    sign_up(user, "carol")\n    assert user.post("/api/admin/questions", json=q).status_code == 403\n\n    boss = TestClient(app)\n    sign_up(boss, "boss")\n    assert boss.post("/api/admin/questions", json=q).status_code == 201\n    assert boss.post("/api/admin/questions", json={**q, "difficulty": 9}).status_code == 400',explain:[{at:'# tests/conftest.py',to:'import tempfile',text:'conftest.py 是 pytest 的“公共准备文件”，放在 tests 文件夹里。tempfile 用来创建临时文件夹。'},{at:'# pytest 在导入任何测试文件之前',to:'os.environ["ADMIN_USERNAMES"] = "boss"',text:'数据库路径和管理员名单都是在导入时读取的（第一个导入 app.database 的文件就决定了用哪个数据库），所以必须在所有测试文件之前设置，写在 conftest.py 里最稳妥。数据库用临时文件夹里的新文件，不碰你真实的数据。（不用 :memory: 内存数据库，因为我们每次查询都新开一个连接，内存数据库每个连接都是空的。）'},{at:'# tests/test_api.py',to:'from main import app',text:'接口测试。TestClient 不用真的启动服务，直接把请求交给 app 处理，还会像浏览器一样记住 Cookie。'},{at:'init_db()',to:'admin_service.migrate()',text:'原来在 if __name__ == "__main__": 里做的准备工作，这里手动做一遍：建表、导入题目、迁移角色列。'},{at:'def sign_up(client, username):',to:'assert client.post("/api/login", json=user).status_code == 200',text:'先注册再登录，每一步都检查状态码。json=… 会自动转成 JSON 正文。'},{at:'def test_login_then_me():',to:'assert client.get("/api/me").status_code == 200',text:'第一个接口测试：没登录 401，登录后 200。'},{at:'def test_admin_needs_role():',to:'q = {',text:'q 是要新增的题目。'},{at:'user = TestClient(app)',to:'assert user.post("/api/admin/questions", json=q).status_code == 403',text:'普通用户：登录了但没有权限，403。'},{at:'boss = TestClient(app)',to:'"difficulty": 9}).status_code == 400',text:'boss 在名单里，注册后就是管理员：新增成功 201；难度不合格 400。'}]}}}},
  {title:'验收：回归测试，前面所有关卡一起检查',body:'这一关的验收脚本是一个“总管”：它找到 checks 文件夹里所有的 check_lN.py，按关卡顺序一个一个运行，看每个脚本最后一行的“通过 n / n”，汇总成一张表。第 3 到 6 关的脚本已经“退休”，会跳过并写明原因。\n因为要把第 14、20、22 关也一起检查，启动后端前要把这几关的环境变量都设置好：\nAI_BASE_URL=http://127.0.0.1:8090，AI_API_KEY=test-key，AI_MODEL=test-model\nOAUTH_MOCK_URL=http://127.0.0.1:8091，GITHUB_CLIENT_ID=gh-id，GITHUB_CLIENT_SECRET=gh-secret，GOOGLE_CLIENT_ID=gg-id，GOOGLE_CLIENT_SECRET=gg-secret\nADMIN_USERNAMES=admin_check\n另外，你自己写的单元测试和接口测试也要全部通过。',practice:{steps:['先运行你的测试命令（Go：go test ./...；Java：mvnw test；Node.js：node --test；Python：python -m pytest），全部通过。','停掉后端，设置好上面的环境变量再启动。把下面的脚本保存为 checks/check_l23.py，运行 python checks/check_l23.py，直到全部 ✓。','以后每次改完代码、提交之前，都把这两步跑一遍。','全部通过后提交：git add . 然后 git commit -m "第 23 关：自动化测试"。'],expect:'✓ check_l2.py（5 / 5）\n- check_l3.py 跳过：第 7 关起题目列表改成了分页，不再返回整个数组\n…\n✓ check_l20.py（8 / 8）\n✓ check_l22.py（8 / 8）\n\n通过 11 / 11'},code:`import re
import subprocess
import sys
from pathlib import Path

BASE = sys.argv[1] if len(sys.argv) > 1 else "http://localhost:8080"
HERE = Path(__file__).resolve().parent
# 已经“退休”的验收脚本：它们检查的是后来有意改掉的旧行为
RETIRED = {
    "check_l3.py": "第 7 关起题目列表改成了分页，不再返回整个数组",
    "check_l4.py": "同上，题目列表的格式变了",
    "check_l5.py": "第 6 关起题目来自数据库，不再是 3 道",
    "check_l6.py": "第 7 关起题目列表改成了分页",
}


def level(path):
    return int(re.search(r"check_l(\\d+)", path.name).group(1))


scripts = sorted((p for p in HERE.glob("check_l*.py") if level(p) < 23), key=level)
failed = []
for script in scripts:
    if script.name in RETIRED:
        print(f"- {script.name} 跳过：{RETIRED[script.name]}")
        continue
    try:
        run = subprocess.run([sys.executable, "-X", "utf8", str(script), BASE],
                             capture_output=True, text=True, encoding="utf-8", timeout=120)
        output = run.stdout + run.stderr
    except subprocess.TimeoutExpired:
        output = "超过 120 秒没有结束"
    found = re.findall(r"通过 (\\d+) / (\\d+)", output)
    ok = bool(found) and found[-1][0] == found[-1][1]
    print(("✓ " if ok else "✗ ") + script.name + (f"（{found[-1][0]} / {found[-1][1]}）" if found else ""))
    if not ok:
        failed.append(script.name)
        bad = [line for line in output.splitlines() if line.startswith("✗")] or output.strip().splitlines()[-3:]
        for line in bad:
            print("    " + line)

total = len([p for p in scripts if p.name not in RETIRED])
print(f"\\n通过 {total - len(failed)} / {total}")
if failed:
    sys.exit(1)`,explain:[{at:'import re',to:'from pathlib import Path',text:'subprocess 用来运行别的程序（这里是别的检查脚本），pathlib 用来找文件。'},{at:'BASE = sys.argv[1]',to:'HERE = Path(__file__).resolve().parent',text:'服务地址；HERE 是这个脚本所在的文件夹，也就是 checks。'},{at:'# 已经“退休”的验收脚本',to:'}',text:'退休名单：文件名 → 原因。需求变了，旧脚本检查的是旧行为，所以跳过，并且写清楚为什么。'},{at:'def level(path):',to:'return int(',text:'从文件名里取出关卡号。按数字排序，check_l10 才会排在 check_l9 后面（按文字排序会排在 check_l2 前面）。'},{at:'scripts = sorted(',to:'failed = []',text:'找到第 2 到 22 关的 check_l*.py（不包括自己和以后的关卡），按关卡号排好；failed 记下没通过的脚本。'},{at:'for script in scripts:',to:'continue',text:'退休的脚本只打印原因，不运行。'},{at:'try:',to:'output = "超过 120 秒没有结束"',text:'用当前这个 Python（sys.executable）运行脚本，把服务地址传给它，收集它打印的所有内容。超过 120 秒算失败，免得卡住。'},{at:'found = re.findall(',to:'print(("✓ " if ok else "✗ ")',text:'找到“通过 n / m”，最后一次出现的 n 等于 m 才算通过。'},{at:'if not ok:',to:'print("    " + line)',text:'没通过时，把这个脚本里打 ✗ 的行（或者最后几行输出）缩进打印出来，方便你定位。'},{at:'total = len(',to:'sys.exit(1)',text:'打印总的通过数。有失败时退出码是 1：以后自动化流程（下一关）可以根据它判断“测试没过，别上线”。'}]},
  {title:'这一关学到了什么',body:'一、测试金字塔：单元测试最多、最快；接口测试把几层连起来；端到端测试最接近真实，也最慢；\n二、好的测试独立、可重复：每个测试用自己的临时数据，不依赖运行顺序；\n三、表格驱动测试：多种情况写成一张表，重点测边界；\n四、可测试的代码结构：把“组装应用”和“启动服务”分开，测试才能在内部启动它；\n五、回归测试：每次修改后把旧的检查都跑一遍；需求变了就让旧检查“退休”，代码坏了就修代码。\n下一关把项目部署到服务器上，并在上线前自动跑一遍测试。'}
 ],quiz:[
 {id:'pj-test-1',q:'“测试金字塔”建议哪一层的测试写得最多？',options:['单元测试','接口测试','端到端测试','手动点击测试'],why:['','接口测试放在中间一层，数量少一些。','端到端测试最慢，放在塔尖，写得最少。','手动测试不在金字塔里，能自动化的尽量自动化。'],answer:0,explain:'单元测试最快、出错时最容易定位，所以最多；越往上越慢、越难定位，数量越少。'},
 {id:'pj-test-2',q:'接口测试为什么要用临时数据库，而不是你平时用的 data/zixishi.db？',options:['让测试独立、可重复','临时数据库的速度更快','平时的数据库不能读','这样能少写几行代码'],why:['','速度不是主要原因。','平时的数据库也能读写，问题是会互相影响。','反而要多写几行准备数据的代码。'],answer:0,explain:'用真实数据库，测试结果会受里面已有数据影响（比如用户名已被注册返回 409），还会把测试数据写进去。每次一个全新的临时数据库，跑多少遍结果都一样。'},
 {id:'pj-test-3',type:'judge',q:'测试题目长度时，“正好 200 个字应该通过”和“201 个字应该失败”这两种情况都值得测。',answer:true,explain:'正确。这叫边界测试：程序最容易在边界上写错（比如把 <= 写成 <），两侧都测才能发现。'},
 {id:'pj-test-4',q:'“表格驱动测试”的主要好处是？',options:['加一种情况只要加一行','测试运行的速度更快','不用再写任何断言','能自动生成测试数据'],why:['','运行速度和写法关系不大。','断言还是要写，只是写一次。','数据还是要自己写在表里。'],answer:0,explain:'检查逻辑只写一遍，每种情况是表里的一行，想多测一种情况加一行就行，也很容易看出哪些情况已经测到了。'},
 {id:'pj-test-5',q:'第 3 关的验收脚本检查“题目列表返回整个数组”，第 7 关改成分页后它失败了，应该怎么办？',options:['让它退休，并写明原因','把分页改回整个数组','删掉所有旧的验收脚本','以后不再运行任何脚本'],why:['','分页是有意的改进，不该为了旧检查改回去。','其他旧脚本还在保护着旧功能，不能全删。','不运行就发现不了真正的回归。'],answer:0,explain:'需求变了，旧检查描述的是旧行为，就让它退休并写清原因。如果是代码改坏了，才去修代码。'},
 {id:'pj-test-6',type:'multi',q:'下面哪些是“好的测试”的特点？（多选）',options:['每个测试自己准备数据','跑多少遍结果都一样','失败时说清期望和实际','依赖上一个测试留下的数据'],why:['','','','依赖运行顺序的测试很脆弱，单独运行或换个顺序就会失败。'],answers:[0,1,2],explain:'独立、可重复、失败信息清楚。测试之间不能互相依赖。'},
 {id:'pj-test-7',type:'fill',q:'以前好好的功能，因为新的修改坏掉了，这种情况叫 ＿。',accepted:['回归','regression','回归问题'],explain:'回归（regression）。每次修改后把旧的检查都跑一遍，就是回归测试。'},
 {id:'pj-test-8',type:'judge',q:'回归测试的总管脚本在有失败时用退出码 1 结束，这样自动化流程能据此判断“测试没过”。',answer:true,explain:'正确。程序的退出码 0 表示成功，非 0 表示失败。下一关的自动部署就会根据测试命令的退出码决定要不要继续。'},
 {id:'pj-test-9',type:'short',q:'我们的项目里有三种测试：单元测试、接口测试、验收脚本。请分别说明它们测的是什么、需不需要先启动服务。',reference:'单元测试：直接调用一个函数（比如 clean），不连数据库、不发请求，不需要启动服务；接口测试：在测试里启动应用、连临时数据库、发真正的 HTTP 请求，测试自己启动服务，不需要你先启动；验收脚本：从外面访问你已经启动的服务，像真实用户一样检查整个系统，需要先启动服务。',points:['单元测试只测一个函数，不需要服务','接口测试在测试内部启动应用和临时数据库','验收脚本访问已经运行的服务，需要先启动'],explain:'三者从下到上，越来越接近真实，也越来越慢。'},
 {id:'pj-test-go-1',stack:'go',q:'Go 测试里 t.Errorf 和 t.Fatalf 的区别是？',options:['Errorf 记下失败继续，Fatalf 立刻停止','Errorf 停止测试，Fatalf 继续执行','两个完全一样，只是名字不同','Fatalf 会让整个程序崩溃退出'],why:['','正好反过来。','行为不同。','Fatalf 只结束当前这个测试函数。'],answer:0,explain:'后面的检查还有意义时用 t.Errorf；准备工作失败、后面没法继续时用 t.Fatalf（比如注册失败了，就没法测登录后的接口）。'},
 {id:'pj-test-java-1',stack:'java',q:'Java 中 @SpringBootTest(webEnvironment = RANDOM_PORT) 的作用是？',options:['启动整个应用，用随机的空闲端口','只创建一个对象，不启动应用','连接正在 8080 端口运行的服务','把测试结果随机打乱顺序显示'],why:['','只创建一个对象是单元测试的做法。','它自己启动一个新的应用，不连你正在运行的服务。','和显示顺序无关。'],answer:0,explain:'测试自己启动完整的应用，端口随机，用 @LocalServerPort 取到端口号，不会和你正在运行的服务冲突。'},
 {id:'pj-test-node-1',stack:'node',q:'Node.js 中 if (require.main === module) 里面的代码，什么时候会执行？',options:['直接 node app.js 运行时','被其他文件 require 时','每次处理请求的时候','运行 node --test 时'],why:['','被 require 时 require.main 是别的文件，不会执行。','它只在启动时判断一次。','测试里是 require 应用，所以不执行。'],answer:0,explain:'require.main 是直接运行的那个文件。这样测试 require 应用时不会去监听 8080 端口、导入数据。'},
 {id:'pj-test-python-1',stack:'python',q:'Python 中为什么把设置 DB_PATH 的代码写在 tests/conftest.py 里？',options:['它在所有测试文件之前运行','pytest 只读取这一个文件','这样测试会运行得更快','环境变量必须在这里设置'],why:['','pytest 会读取所有 test_ 开头的文件。','和速度无关。','在哪里都能设置，关键是时机。'],answer:0,explain:'app.database 在第一次被导入时读取 DB_PATH。conftest.py 在所有测试文件之前运行，在这里设置，才能保证每个测试都用临时数据库。'}]};
